function validate([operations, args]) {
  const memoryLimit = args[0][0];
  if (memoryLimit < 2 || memoryLimit > 100000) return 'memoryLimit is between 2 and 10^5.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls after the constructor.';
  let last = 0;
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] === 'addPacket') {
      const [source, destination, timestamp] = args[i];
      if (source < 1 || source > 200000 || destination < 1 || destination > 200000) return 'source and destination are between 1 and 2 * 10^5.';
      if (timestamp < 1 || timestamp > 1000000000) return 'timestamp is between 1 and 10^9.';
      if (timestamp < last) return 'addPacket timestamps must never decrease.';
      last = timestamp;
    } else if (operations[i] === 'getCount') {
      const [destination, startTime, endTime] = args[i];
      if (destination < 1 || destination > 200000) return 'destination is between 1 and 2 * 10^5.';
      if (!(1 <= startTime && startTime <= endTime && endTime <= 1000000000)) return 'getCount needs 1 <= startTime <= endTime <= 10^9.';
    }
  }
  return null;
}

