class Router {
  constructor(memoryLimit) {
    this.memoryLimit = memoryLimit;
    this.queue = [];
    this.head = 0;
    this.stored = new Set();
    this.byDestination = new Map();
  }

  addPacket(source, destination, timestamp) {
    const packet = [source, destination, timestamp];
    const key = packet.join(',');
    if (this.stored.has(key)) {
      return false;
    }
    if (this.queue.length - this.head === this.memoryLimit) {
      this.forwardPacket();
    }
    this.queue.push(packet);
    this.stored.add(key);
    if (!this.byDestination.has(destination)) {
      this.byDestination.set(destination, { times: [], first: 0 });
    }
    this.byDestination.get(destination).times.push(timestamp);
    return true;
  }

  forwardPacket() {
    if (this.head === this.queue.length) {
      return [];
    }
    const packet = this.queue[this.head];
    this.head++;
    this.stored.delete(packet.join(','));
    this.byDestination.get(packet[1]).first++;
    return packet;
  }

  getCount(destination, startTime, endTime) {
    const group = this.byDestination.get(destination);
    if (group === undefined) {
      return 0;
    }
    return this.lowerBound(group, endTime + 1) - this.lowerBound(group, startTime);
  }

  lowerBound(group, value) {
    let low = group.first;
    let high = group.times.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (group.times[mid] < value) {
        low = mid + 1;
      } else {
        high = mid;
      }
    }
    return low;
  }
}

