class Router {
  // A plain list of stored packets, oldest first, scanned in full on every call.
  constructor(memoryLimit) {
    this.limit = memoryLimit;
    this.packets = [];
  }
  addPacket(source, destination, timestamp) {
    if (this.packets.some(p => p[0] === source && p[1] === destination && p[2] === timestamp)) return false;
    if (this.packets.length === this.limit) this.packets.shift();
    this.packets.push([source, destination, timestamp]);
    return true;
  }
  forwardPacket() {
    return this.packets.length > 0 ? this.packets.shift() : [];
  }
  getCount(destination, startTime, endTime) {
    return this.packets.filter(p => p[1] === destination && startTime <= p[2] && p[2] <= endTime).length;
  }
}

