function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const memoryLimit = large ? (rand() < 0.3 ? 100000 : int(2, 300)) : int(2, 5);
  const ids = large ? (rand() < 0.5 ? 20 : 200000) : 3;
  const calls = large ? 499 : int(1, 25);
  const operations = ['Router'];
  const args = [[memoryLimit]];
  const added = [];
  let time = large ? int(1, 999000000) : int(1, 5);
  for (let c = 0; c < calls; c++) {
    const pick = rand();
    if (pick < 0.55) {
      if (rand() < 0.5) time += int(1, large ? 1000 : 2);
      let source = int(1, ids), destination = int(1, ids);
      // Sometimes resend a recent packet with the current timestamp, which may be a duplicate.
      const recent = added[added.length - 1 - int(0, 2)];
      if (recent && recent[2] === time && rand() < 0.4) [source, destination] = recent;
      operations.push('addPacket');
      args.push([source, destination, time]);
      added.push([source, destination, time]);
    } else if (pick < 0.75) {
      operations.push('forwardPacket');
      args.push([]);
    } else {
      const destination = added.length && rand() < 0.85 ? added[int(0, added.length - 1)][1] : int(1, ids);
      const wide = rand() < 0.15;
      const startTime = wide ? 1 : Math.max(1, time - int(0, large ? 5000 : 6));
      const endTime = wide ? 1000000000 : Math.min(1000000000, startTime + int(0, large ? 5000 : 6));
      operations.push('getCount');
      args.push([destination, startTime, endTime]);
    }
  }
  return [operations, args];
}
